#pragma once
namespace ff3Assist {
inline bool renderInterception(Gdiplus::Graphics& g,const ff3Native::Frame& frame,const VisualState& state,const FeatureConfig& config,double time){
 using namespace Gdiplus;const auto& p=state.interception;const double age=time-p.plannedAt;
 if(!config.on||!p.valid||state.possessed||age<0||age>.38||time>=p.contactAt+.05)return false;
 const int w=frame.client.right,h=frame.client.bottom;const double fade=std::clamp((.38-age)/.1,0.,1.);bool drawn=false;
 const Color base=!p.reachable?Color(255,255,191,115):p.action==InterceptionAction::Dive||p.action==InterceptionAction::JumpDive?Color(255,186,170,255):p.action==InterceptionAction::Jump?Color(255,104,237,205):Color(255,137,207,255);
 auto ink=[&](int alpha){return Color(BYTE(alpha*fade),base.GetR(),base.GetG(),base.GetB());};
 auto world=[&](Vec v){return ff3qb::project(v,frame.matrix,w,h);};
 auto segment=[&](Vec a,Vec b,int alpha,float width){ff3qb::Screen u,v;if(!ff3OobVisual::segment(a,b,frame.matrix,w,h,u,v))return;Pen shadow(Color(BYTE(150*fade),7,14,24),width+2),core(ink(alpha),width);core.SetStartCap(LineCapRound);core.SetEndCap(LineCapRound);g.DrawLine(&shadow,float(u.x),float(u.y),float(v.x),float(v.y));g.DrawLine(&core,float(u.x),float(u.y),float(v.x),float(v.y));drawn=true;};
 auto text=[&](Vec at,const std::wstring& title,const std::wstring& detail){const auto q=world(at);if(!q.valid)return;Font font(L"Segoe UI",13,FontStyleBold,UnitPixel),subFont(L"Segoe UI",10.5f,FontStyleRegular,UnitPixel);RectF a,b;g.MeasureString(title.c_str(),-1,&font,PointF(0,0),&a);g.MeasureString(detail.c_str(),-1,&subFont,PointF(0,0),&b);const float width=std::max(a.Width,b.Width)+26,height=detail.empty()?31.f:47.f,x=float(std::clamp(q.x-width*.5,8.,std::max(8.,w-width-8.))),y=float(std::clamp(q.y-height-24.,8.,std::max(8.,h-height-8.)));GraphicsPath box;const float r=9;box.AddArc(x,y,r,r,180,90);box.AddArc(x+width-r,y,r,r,270,90);box.AddArc(x+width-r,y+height-r,r,r,0,90);box.AddArc(x,y+height-r,r,r,90,90);box.CloseFigure();SolidBrush bg(Color(BYTE(235*fade),13,22,33)),fg(ink(250)),secondary(Color(BYTE(220*fade),200,215,227));Pen edge(ink(100),1);g.FillPath(&bg,&box);g.DrawPath(&edge,&box);StringFormat centered;centered.SetAlignment(StringAlignmentCenter);g.DrawString(title.c_str(),-1,&font,RectF(x,y+6,width,20),&centered,&fg);if(!detail.empty())g.DrawString(detail.c_str(),-1,&subFont,RectF(x,y+27,width,16),&centered,&secondary);drawn=true;};
 auto heading=unit(flat(p.heading));if(ff3qb::length(heading)<.5)heading=unit(flat(p.contact-p.moveTo));const Vec right{-heading.z,0,heading.x};
 auto pad=[&](Vec center,bool dive,double actionTime,bool label){center.y=state.ground+.09;const double halfWidth=dive?2.25:2.8,halfLength=dive?3.8:2.5;std::vector<PointF> polygon;for(auto local:{Vec{-halfWidth,0,-halfLength+.6},Vec{-halfWidth+.6,0,-halfLength},Vec{halfWidth-.6,0,-halfLength},Vec{halfWidth,0,-halfLength+.6},Vec{halfWidth,0,halfLength-.6},Vec{halfWidth-.6,0,halfLength},Vec{-halfWidth+.6,0,halfLength},Vec{-halfWidth,0,halfLength-.6}}){auto q=world(center+right*local.x+heading*local.z);if(!q.valid){polygon.clear();break;}polygon.emplace_back(float(q.x),float(q.y));}
  if(polygon.size()>=3){GraphicsPath path;path.AddPolygon(polygon.data(),INT(polygon.size()));SolidBrush fill(ink(38));Pen glow(ink(18),9.f),shadow(Color(BYTE(200*fade),8,17,27),4.6f),edge(ink(230),2.2f);glow.SetLineJoin(LineJoinRound);shadow.SetLineJoin(LineJoinRound);edge.SetLineJoin(LineJoinRound);g.FillPath(&fill,&path);g.DrawPath(&glow,&path);g.DrawPath(&shadow,&path);g.DrawPath(&edge,&path);drawn=true;}
  for(double z:{-.7,.5}){auto tip=center+heading*(z+.65);segment(tip,tip-heading*.8+right*.8,245,2.1f);segment(tip,tip-heading*.8-right*.8,245,2.1f);}
  if(label){const double remaining=std::max(0.,actionTime-time);wchar_t when[100];if(!p.reachable)swprintf_s(when,L"Closest attempt · %.1f st short",p.miss);else if(remaining<.1)swprintf_s(when,L"NOW · catch input required");else swprintf_s(when,L"in %.2f s · catch input required",remaining);const auto title=!p.reachable?L"OUT OF REACH":dive?L"DIVE HERE":p.action==InterceptionAction::Run?L"INTERCEPT HERE":p.action==InterceptionAction::Reach?L"REACH HERE":p.action==InterceptionAction::JumpDive?L"JUMP → DIVE":L"JUMP HERE";text(center,title,when);}
 };
 const bool firstPassed=p.action==InterceptionAction::JumpDive&&time>p.jumpAt+.07;
 if(p.action==InterceptionAction::JumpDive){if(!firstPassed)pad(p.jumpAtPoint,false,p.jumpAt,true);if(firstPassed||distance(p.jumpAtPoint,p.diveAtPoint)>4)pad(p.diveAtPoint,true,p.diveAt,firstPassed);}
 else pad(p.moveTo,p.action==InterceptionAction::Dive,p.actionAt,true);
 if(config.b(L"contact",true)){const auto q=world(p.contact);if(q.valid){const float x=float(q.x),y=float(q.y);const double remain=std::max(0.,p.contactAt-time),progress=1-std::clamp(remain/std::max(.1,p.contactAt-p.selectedAt),0.,1.);Pen halo(ink(35),7),edge(ink(225),1.8f),progressPen(ink(255),2.6f);g.DrawEllipse(&halo,x-10,y-10,20.f,20.f);g.DrawEllipse(&edge,x-10,y-10,20.f,20.f);g.DrawArc(&progressPen,x-14,y-14,28.f,28.f,-90.f,float(progress*360));g.DrawLine(&edge,x-4,y,x+4,y);g.DrawLine(&edge,x,y-4,x,y+4);if(config.b(L"race",true)&&p.raceKnown){wchar_t label[100];swprintf_s(label,p.advantage>=.08?L"EST. +%.2fs BEFORE OTHERS":L"CONTESTED · EST. %.2fs",std::abs(p.advantage));text(p.contact+Vec{0,1,0},L"CONTACT WINDOW",label);}drawn=true;}}
 return drawn;
}
}
